import { EnumMatch } from "../../data/enumData/EnumMatch";
import Constants from "../../global/config/Constants";
import MatchModel from "../../modules/match/MatchModel";
import Tool from "../../utils/Tool";
import Snake from "../snake/Snake";
import SnakeManager from "../snake/SnakeManager";

class MapManager {
    private static _instance: MapManager = null;

    private _gameMap: Laya.Sprite;

    public img_smallMap: Laya.Image;

    public get gameMap(): Laya.Sprite {
        return this._gameMap;
    }
    public set gameMap(value: Laya.Sprite) {
        this._gameMap = value;
    }

    public static getInstance(): MapManager {
        if (!MapManager._instance) {
            MapManager._instance = new MapManager();
        }
        return MapManager._instance;
    }

    constructor() {}

    public init(): void {}

    destroy() {
        this._gameMap = null;
        this.img_smallMap = null;
        this.myHeroSpr = null;
        this.targetHeroSpr = null;
        this.otherHeroSpr = null;
        // this.moveP = null;
    }

    moveType: number;
    mapDir: number = -4;
    moveP: Laya.Point = new Laya.Point();
    /**
     * 设置跟随自己的蛇
     */
    public myHeroSpr: Snake;
    /**
     * 显示蛇信息的蛇
     */
    public targetHeroSpr: Snake;
    /**
     * 设置跟随的其他蛇
     */
    public otherHeroSpr: Snake;

    public setCurrentHero(hero: Snake) {
        var isWatcher = MatchModel.matchWatcher;

        if (isWatcher) {
        } else {
            this.myHeroSpr = hero;
            this.moveType = EnumMatch.CAMERA_FOLLOW_ME; //设置跟随自己的蛇

            this.moveGameWindow(true); // 设置游戏窗口
        }
    }
    public setOtherHero(hero: Snake) {
        console.log("========= setOtherHero: 1", hero, this.otherHeroSpr);
        if (this.otherHeroSpr) {
            if (this.otherHeroSpr == hero) {
                //如果再次点击则取消跟随模式
                this.targetHeroSpr = null;
                this.setCameraIdle();
                return;
            }
        }
        console.log("========= setOtherHero: 2", hero, this.otherHeroSpr);
        this.removeOtherHero();
        hero.setFollowIcon(true);
        this.otherHeroSpr = hero;
        this.targetHeroSpr = hero;
        this.moveType = EnumMatch.CAMERA_FOLLOW_OTHER; //设置跟随他人的蛇
        this.moveGameWindow(true); // 设置游戏窗口
    }

    private setCameraIdle() {
        this.removeOtherHero();
        this.moveType = EnumMatch.CAMERA_IDLE; //设置 静止模式
        this.moveGameWindow(true); // 设置游戏窗口
    }
    private removeOtherHero() {
        if (this.otherHeroSpr && this.otherHeroSpr.tag) {
            this.otherHeroSpr.setFollowIcon(false);
        }
        this.otherHeroSpr = null;
    }

    /**
     * 点击小地图, 移动到对应大地图窗口
     * @param smallP
     */
    clickSmallMapToMove(smallP: Laya.Point) {
        this.removeOtherHero();
        var bigP = Tool.fromSmallToBig(smallP.x, smallP.y);

        this.moveP.setTo(bigP[0], bigP[1]);
        this.moveType = EnumMatch.CAMERA_MAP_CLICK;
        this.moveGameWindow(true);
    }
    /**
     * 移动游戏窗口以使位置始终居中
     *  */
    moveGameWindow(immediately: boolean = false) {
        if (this.moveType == EnumMatch.CAMERA_IDLE) {
            //0 = 静止模式
            return;
        } else if (this.moveType == EnumMatch.CAMERA_FOLLOW_ME) {
            //1 = 默认跟随自己的蛇
            if (!this.myHeroSpr) return;
            var myPos = this.myHeroSpr.getHeadPosition(false);
            this.moveP.setTo(myPos.x, myPos.y);
        } else if (this.moveType == EnumMatch.CAMERA_FOLLOW_OTHER) {
            //4 = 跟随其他的蛇
            if (!this.otherHeroSpr) return;
            if (this.otherHeroSpr.tag && this.otherHeroSpr.isAlive(false)) {
                var otherPos = this.otherHeroSpr.getHeadPosition(false);
                this.moveP.setTo(otherPos.x, otherPos.y);
            } else {
                var nextSnake = SnakeManager.getInstance().getFirstSnake();
                if (nextSnake && nextSnake.tag && nextSnake.isAlive(false)) {
                    this.setOtherHero(nextSnake);
                } else {
                    // this.targetHeroSpr = null;
                    this.setCameraIdle(); //跟随蛇阵亡时，自动退出跟随模式
                }
            }
        } else if (this.moveType == EnumMatch.CAMERA_MAP_CLICK) {
            //2 = 点击小地图，可直接切换到点击位置
            if (!this.moveP) return;
        } else if (this.moveType == EnumMatch.CAMERA_DIRECT_OPERATE) {
            //3 = 可操控方向键，移动镜头，移动速度要比蛇移动的速度略快，大约是1.3-1.5倍）
            if (!this.moveP) return;

            if (this.mapDir != -4) {
                // 将角度转换为向量
                const speed = 10 * 1.4;
                const magnitude = 1 * speed; // 向量的长度，如果需要单位向量，则为1

                const angleRadians = this.mapDir * (Math.PI / 180); // 将角度转换为弧度
                const vectorX = magnitude * Math.cos(angleRadians);
                const vectorY = magnitude * Math.sin(angleRadians);

                // console.log("Vector X: ", vectorX, "Vector Y: ", vectorY, "speed: ", speed, "roleDirection: ", this.mapDir);

                var movePX = Math.round(this.moveP.x + vectorX);
                var movePY = Math.round(this.moveP.y + vectorY);

                var gameMapX = -(movePX - Laya.stage.width / 2);
                var gameMapY = -(movePY - Laya.stage.height / 2);
                // this.gameWindowX = movePX - Laya.stage.width / 2;
                // this.gameWindowY = movePY - Laya.stage.height / 2;

                // var gameMapX = -this.gameWindowX;
                // var gameMapY = -this.gameWindowY;
                var deW = Laya.stage.width - this.gameMap.width;
                var deH = Laya.stage.height - this.gameMap.height;

                console.log(
                    "moveGameWindow: gameMap ",
                    this.moveType,
                    immediately,
                    gameMapX,
                    gameMapY,
                    Laya.stage.width,
                    Laya.stage.height,
                    this.gameMap.x,
                    this.gameMap.y
                );
                if (gameMapX > 0) {
                    movePX = this.moveP.x;
                    // gameMapX = 0;
                } else if (gameMapX < deW) {
                    movePX = this.moveP.x;
                    // gameMapX = deW;
                } else {
                    // gameMapX = gameMapX;
                }

                if (gameMapY > 0) {
                    movePY = this.moveP.y;
                    // gameMapY = 0;
                } else if (gameMapY < deH) {
                    movePY = this.moveP.y;
                    // gameMapY = deH;
                } else {
                    // gameMapY = gameMapY;
                }

                this.moveP.setTo(movePX, movePY);
                immediately = true;
                // this.moveGameWindow();
            } else {
                return;
            }
        }

        this.move(immediately);
    }

    setMapDirection(direction: number) {
        if (!this.moveP) {
            console.log("setMyHeroDirection: " + this.moveP);
            return;
        }

        if (this.moveType != EnumMatch.CAMERA_DIRECT_OPERATE) {
            this.removeOtherHero();
            this.moveType = EnumMatch.CAMERA_DIRECT_OPERATE;
            this.setMapPos();
        }
        this.mapDir = direction;
    }
    private setMapPos() {
        var movePX = Laya.stage.width / 2 - this.gameMap.x;
        var movePY = Laya.stage.height / 2 - this.gameMap.y;
        this.moveP.setTo(movePX, movePY);
    }
    /**
     * 根据蛇位置移动地图（调整 root 节点的位置）
     * @param this.moveP 蛇当前坐标
     */
    public move(immediately: boolean): void {
        // return;
        if (!this.moveP) return;
        const mapSize = Constants.mapSize;
        const winWidth = Laya.stage.width;
        const winHeight = Laya.stage.height;

        var gameMapX = 0;
        var gameMapY = 0;
        // 横向移动
        if (this.moveP.x > winWidth / 2 && this.moveP.x < mapSize.width - 0.5 * winWidth) {
            gameMapX = -(this.moveP.x - winWidth / 2);
        } else if (this.moveP.x <= winWidth / 2) {
            gameMapX = 0;
        } else if (this.moveP.x >= mapSize.width - 0.5 * winWidth) {
            gameMapX = -(mapSize.width - winWidth);
        }
        // 纵向移动
        if (this.moveP.y > winHeight / 2 && this.moveP.y < mapSize.height - 0.5 * winHeight) {
            gameMapY = -(this.moveP.y - winHeight / 2);
        } else if (this.moveP.y <= winHeight / 2) {
            gameMapY = 0;
        } else if (this.moveP.y >= mapSize.height - 0.5 * winHeight) {
            gameMapY = -(mapSize.height - winHeight);
        }
        if (!immediately) {
            var positionError = Tool.distancePoint(gameMapX, gameMapY, this.gameMap.x, this.gameMap.y);

            if (positionError < 200) {
                // alpha 越小，校正越慢；通常可以根据帧率或时间差动态调整
                const alpha = 0.3; // 平滑系数（0到1之间），例如每帧调整10%

                // 逐步将本地蛇头位置插值到服务器蛇头位置
                gameMapX = Tool.lerp(this.gameMap.x, gameMapX, alpha);
                gameMapY = Tool.lerp(this.gameMap.y, gameMapY, alpha);
            }
        }

        this.gameMap.pos(gameMapX, gameMapY);

        // Laya.Tween.to(root, { x: gameMapX, y: gameMapY }, 0);
    }
}

export default MapManager.getInstance();
