const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import { ReferralQRDialogBase } from "./ReferralQRDialog.generated";
import { Quick } from "../../utils/Quick";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import NoticeMgr from "../notice/NoticeMgr";
declare const QRCode: any;

@regClass('Al5bWuKZR16XVkgipvpL8A==')
export class ReferralQRDialog extends ReferralQRDialogBase {
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;

    public constructor(_data: any) {
        super();
    }

    onEnable(): void {
        this.btn_close.on(Laya.Event.CLICK, this, this.onClickBackHome);
        this.updateReferralInfo();
        this.showQrcode();
        this.btn_copy.on(Laya.Event.CLICK, this, this.onCopy);
    }

    onDisable(): void {
        Laya.timer.clearAll(this);
        this.btn_close.off(Laya.Event.CLICK, this, this.onClickBackHome);
    }

    private onClickBackHome() {
        this.close()
    }

       /**
 * 更新邀请码信息
 */
    private updateReferralInfo(): void {
        let playerDto = GlobalDataManager.playerDto;
        if (playerDto.code) {
            this.tf_code.text = playerDto.code;
        }
    }

    /**
     * 个人邀请码复制
    */
    onCopy() {
        let code = this.tf_code.text;
        const shareUrl = Quick.getInviteUrl(code);

        doCopy(shareUrl);

        NoticeMgr.notice(GameLanguageMgr.getLanguage(19)); //复制成功
    }

    private showQrcode(): void {
        let code = this.tf_code.text;
        let shareUrl = Quick.getInviteUrl(code);
        // 检查并移除URL中的telegramConnect部分
        // 判断如果有telegramConnect字段的话就去掉
        if (shareUrl.includes("telegramConnect/")) {
            shareUrl = shareUrl.replace("telegramConnect/", "");
        }
        try {
            // 创建临时DOM元素用于生成二维码
            const qrElement = document.createElement('div');
            qrElement.id = 'tempQrCode';
            document.body.appendChild(qrElement);
            
            // 图标URL，可以根据需要更改
            // const iconUrl = "res/role/role2/img_gameicon.png"; // 这里配置您的图标地址
            const iconUrl = "https://static.cryptoarena.io/images/gameIcon/img_gameicon.png"; // 这里配置您的图标地址

            // 使用QRCode库生成二维码
            const qrcode = new QRCode(qrElement, {
                text: shareUrl,
                width: 220,
                height: 220,
                colorDark: '#165daf',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.L
            });
            
            // 使用setTimeout确保二维码已渲染完成
            setTimeout(() => {
                try {
                    // 从Canvas获取二维码图像数据
                    const canvas = qrElement.querySelector('canvas');
                    if (canvas) {
                        // 创建新的canvas元素用于合成图像
                        const compositeCanvas = document.createElement('canvas');
                        compositeCanvas.width = canvas.width;
                        compositeCanvas.height = canvas.height;
                        const ctx = compositeCanvas.getContext('2d');
                        
                        // 先绘制二维码
                        ctx.drawImage(canvas, 0, 0, canvas.width, canvas.height);
                        
                        // 加载图标
                        const icon = new Image();
                        icon.crossOrigin = "anonymous"; // 处理跨域问题
                        icon.onload = () => {
                            // 计算图标位置（居中）
                            const iconSize = canvas.width * 0.25; // 图标大小为二维码的25%
                            const iconX = (canvas.width - iconSize) / 2;
                            const iconY = (canvas.height - iconSize) / 2;
                            
                            // 绘制白色背景（可选，使图标更清晰）
                            ctx.fillStyle = 'white';
                            ctx.fillRect(iconX, iconY, iconSize, iconSize);
                            
                            // 绘制图标
                            ctx.drawImage(icon, iconX, iconY, iconSize, iconSize);
                            
                            // 获取合成后的图像
                            const dataUrl = compositeCanvas.toDataURL('image/png');
                            
                            // 设置img_qrCode的skin属性
                            this.img_qrCode.skin = dataUrl;
                            this.img_qrCode.visible = true;
                            
                            // 移除临时DOM元素
                            document.body.removeChild(qrElement);
                        };
                        
                        icon.onerror = () => {
                            console.error("加载图标失败");
                            // 如果图标加载失败，仍使用原始二维码
                            this.img_qrCode.skin = canvas.toDataURL('image/png');
                            this.img_qrCode.visible = true;
                            document.body.removeChild(qrElement);
                        };
                        
                        // 设置图标源
                        icon.src = iconUrl;
                        
                    } else {
                        // 无法获取Canvas，尝试获取img元素
                        const qrImg = qrElement.querySelector('img');
                        if (qrImg && qrImg.src) {
                            // 直接设置img_qrCode的skin属性
                            this.img_qrCode.skin = qrImg.src;
                            this.img_qrCode.visible = true;
                            document.body.removeChild(qrElement);
                        } else {
                            console.error("无法获取二维码图像");
                            document.body.removeChild(qrElement);
                        }
                    }
                } catch (e) {
                    console.error("获取二维码图像失败:", e);
                    // 确保临时DOM元素被移除
                    document.body.removeChild(qrElement);
                }
            }, 100); // 等待100ms确保二维码渲染完成
        } catch (e) {
            console.error("生成二维码失败:", e);
        }
    }
}
