const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { ScoreNumberBase } from "./ScoreNumber.generated";

@regClass('rQ126fYrRWisGB61y9Fzcw==')
export class ScoreNumber extends ScoreNumberBase {

    static TYPE_Normal: string = "Normal";
    static TYPE_Kill: string = "Kill";

    onEnable(): void {
        // 初始化时不需要设置文本
    }

    /**
     * 初始化函数，设置得分显示
     * @param score 得分值
     * @param yPosition Y轴位置
     * @param xPosition X轴位置
     * @param animTime 动画时间（毫秒）
     * @param fontSize 字体大小
     */
    init(score: number, yPosition: number, xPosition: number, animTime: number = 1000) {
        // 设置初始位置
        this.y = yPosition;
        this.x = xPosition; // 水平居中显示
        
        // 显示得分
        this.tf_score.text = "+" + score;
        
        // 重置透明度和缩放
        this.alpha = 1;
        // this.scale(1, 1);
        
        // 开始动画效果：向上移动并淡出
        Laya.Tween.to(
            this, 
            { 
                y: yPosition - 80,  // 向上移动80像素
                alpha: 0  // 完全透明
            }, 
            animTime, 
            Laya.Ease.quartOut,  // 使用四次方缓出效果
            Laya.Handler.create(this, this.onComplete)
        );
    }

    // 动画完成时的处理
    onComplete() {
        // 从父节点移除并回收
        this.removeSelf();
    }

    onDisable(): void {
        Laya.Pool.recover("ScoreNumber", this);
    }
}
