const { regClass } = Laya;
import GameSetting from "../../global/GameSetting";
import GlobalDataManager from "../../global/GlobalDataManager";
import HttpCmd from "../../network/HttpCmd";
import { BannerViewBase } from "./BannerView.generated";

@regClass('X02Uvn1OTF2XLiT4Dvmmnw==')
export class BannerView extends BannerViewBase {
    private banners: any[] = [
    ];

    private currentIndex: number = 0;
    // private timer: any;
    private isAnimating: boolean = false;
    private startX: number = 0;
    private startY: number = 0;
    private isDragging: boolean = false;
    private dragThreshold: number = 50;
    private adAddress: string = "";
    private adDuration: number = 15000;

    // private bannerImgX:number;

    onEnable(): void {
        // this.bannerImgX = this.bannerImg.x;
        // 初始化UI
        if (GlobalDataManager.bannerData.length <= 0) {
            this.getBannerAd();
        }
        this.banners = GlobalDataManager.bannerData;
        // this.updateBanner();
        this.createIndicators();
        this.bannerImg.on(Laya.Event.CLICK, this, this.onWatchAD);
        // 添加事件监听
        // this.leftBtn.on("click", this, this.prevBanner);
        // this.rightBtn.on("click", this, this.nextBanner);
        this.btn_closeBanner.on(Laya.Event.CLICK, this, this.hideBannerBox);
        // 添加触摸事件
        this.on(Laya.Event.MOUSE_DOWN, this, this.onMouseDown);
        this.on(Laya.Event.MOUSE_MOVE, this, this.onMouseMove);
        this.on(Laya.Event.MOUSE_UP, this, this.onMouseUp);
        this.on(Laya.Event.MOUSE_OUT, this, this.onMouseUp);
        this.visible = false;
        // 自动轮播
        // this.startAutoPlay();

        // // 响应式调整
        // Laya.stage.on(Laya.Event.RESIZE, this, this.onResize);
        // this.onResize();
    }

    /**
     * 根据不同游戏获取相应的广告
     */
    private getBannerAd(): any {
        let language = "zhCN";
        switch (GlobalDataManager.m_strLanguage) {
            case 1:
                language = "en";
                break;
            case 6:
                language = "zh";
                break;
            case 7:
                language = "zhCN";
                break;
        }

        let placementCode = "TETRIS-HALL"
        switch (GameSetting.gameId) {
            case 100001:
                placementCode = "SNAKE-HALL"
                break;
            case 100002:
                placementCode = "XXL-HALL"
                break;
            case 100003:
                placementCode = "TETRIS-HALL"
                break;

        }
        let address
        let apiUrl;
        if (GameSetting.vType == 0) {
            apiUrl = `http://13.250.6.10:8081/app-api/placement/frontQuery?lang=${language}&placementCode=${placementCode}`
        }else if(GameSetting.vType == 1){
            apiUrl = `http://52.77.236.74/app-api/placement/frontQuery?lang=${language}&placementCode=${placementCode}`
        } else {
            address = `/app-api/placement/frontQuery?lang=${language}&placementCode=${placementCode}`
            apiUrl = "https://cryptoarena.io" + address;
        }
        HttpCmd.requestGet(apiUrl, {}, false)
            .then((response: any) => {
                if (response && (response.code === 200 || response.code === 0) && response.data !== undefined) {
                    console.log("广告数据:", response);
                    if (response.data && response.data.length >= 0) {
                        this.adDuration = response.data[0]?.adDuration * 1000;
                        GlobalDataManager.bannerData = [...response.data[0].images];
                        if(!GlobalDataManager.hideBanner){
                            this.visible = true;
                        }
                    }
                    // if(GlobalDataManager.bannerData.length <= 0) this.visible = false
                    this.banners = GlobalDataManager.bannerData;
                    this.updateBanner();
                    this.createIndicators();
                    this.startAutoPlay();
                }
            })
            .catch((error: any) => {
                console.error(error);
            });
    }

    private updateBanner(): void {
        if (this.isAnimating) return;
        if (this.banners.length <= 0) return;

        this.isAnimating = true;
        const banner = this.banners[this.currentIndex];
        let adData = banner;
        this.bannerImg.skin = adData.imageUrl;
        this.adAddress = adData.herfUrl;
        Laya.Tween.from(
            this.bannerImg,
            { alpha: 0 },
            600,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                this.isAnimating = false;
            })
        );

        // 更新指示器
        this.updateIndicators();
    }

    private createIndicators(): void {
        this.indicatorBox.removeChildren();
        var indicatorBoxW = 0;
        var offsetX = 30;

        for (let i = 0; i < this.banners.length; i++) {
            const indicator = new Laya.Box();
            indicator.size(12, 12);
            indicator.graphics.drawCircle(6, 6, 6, i === this.currentIndex ? "#fff191" : "#191606");
            indicator.pos(i * offsetX, 0);
            indicator.name = i.toString();
            indicator.on("click", this, this.goToBanner);
            this.indicatorBox.addChild(indicator);
        }

        if (this.banners.length > 0) {
            indicatorBoxW = (this.banners.length - 1) * offsetX + 12;
        }

        this.indicatorBox.pos((this.width - indicatorBoxW) / 2, this.height - 40);
    }

    private updateIndicators(): void {
        for (let i = 0; i < this.indicatorBox.numChildren; i++) {
            const indicator = this.indicatorBox.getChildAt(i) as Laya.Box;
            indicator.graphics.clear();
            indicator.graphics.drawCircle(6, 6, 6, parseInt(indicator.name) === this.currentIndex ? "#fff191" : "#191606");
        }
    }

    private goToBanner(e: Laya.Event): void {
        const index = parseInt(e.target.name);
        if (index !== this.currentIndex) {
            this.currentIndex = index;
            this.updateBanner();
            this.resetAutoPlay();
        }
    }

    private nextBanner(): void {
        if (this.isAnimating) return;

        this.currentIndex = (this.currentIndex + 1) % this.banners.length;
        this.updateBanner();
        this.resetAutoPlay();
    }

    private prevBanner(): void {
        if (this.isAnimating) return;

        this.currentIndex = (this.currentIndex - 1 + this.banners.length) % this.banners.length;
        this.updateBanner();
        this.resetAutoPlay();
    }

    private startAutoPlay(): void {
        Laya.timer.loop(this.adDuration, this, this.nextBanner);
        // this.timer = Laya.timer.loop(3000, this, this.nextBanner);
    }

    private resetAutoPlay(): void {
        Laya.timer.clear(this, this.nextBanner);
        this.startAutoPlay();
    }

    private onMouseDown(e: Laya.Event): void {
        this.startX = e.stageX;
        this.startY = e.stageY;
        this.isDragging = true;
        Laya.timer.clear(this, this.nextBanner);
    }

    private onMouseMove(e: Laya.Event): void {
        if (!this.isDragging || this.isAnimating) return;

        const deltaX = e.stageX - this.startX;
        const deltaY = e.stageY - this.startY;

        // 如果是垂直滑动，不处理
        if (Math.abs(deltaY) > Math.abs(deltaX)) {
            return;
        }

        // 设置滑动反馈效果
        // this.bgBox.x = deltaX * 0.5;
        // this.bannerImg.x = this.bannerImgX + deltaX * 0.3;

        // 透明度变化
        const alpha = 1 - Math.abs(deltaX) / 300;
        // this.bgBox.alpha = alpha > 0.7 ? alpha : 0.7;
        this.bannerImg.alpha = alpha > 0.7 ? alpha : 0.7;
    }

    private onMouseUp(e: Laya.Event): void {
        if (!this.isDragging) return;

        this.isDragging = false;
        const deltaX = e.stageX - this.startX;

        // 滑动距离超过阈值则切换
        if (Math.abs(deltaX) > this.dragThreshold) {
            if (deltaX > 0) {
                this.prevBanner();
            } else {
                this.nextBanner();
            }
        } else {
            // 滑动距离不足，恢复原位
            // Laya.Tween.to(this.bgBox, { x: 0, alpha: 1 }, 200);
            // Laya.Tween.to(this.bannerImg, { x: this.bannerImgX }, 200);
            Laya.Tween.to(this.bannerImg, { alpha: 1 }, 200);
        }

        // 重新开始自动轮播
        this.resetAutoPlay();
    }

    // private onResize(): void {
    //     // 响应式布局
    //     this.width = Math.min(Laya.stage.width, 800);
    //     this.height = Math.min(Laya.stage.height * 0.3, 300);

    //     // 重新定位元素
    //     this.bgBox.size(this.width, this.height);
    //     this.titleLabel.pos(this.width / 2, this.height * 0.3);
    //     this.descLabel.pos(this.width / 2, this.height * 0.5);
    //     this.bannerImg.pos(100, this.height / 2 - 50);
    //     this.leftBtn.pos(20, this.height / 2 - 20);
    //     this.rightBtn.pos(this.width - 60, this.height / 2 - 20);
    //     this.indicatorBox.pos((this.width - this.indicatorBox.width) / 2, this.height - 30);
    // }
    private hideBannerBox() {
        GlobalDataManager.hideBanner = true
        // this.btn_closeJoin.visible = false;
        Laya.Tween.to(
            this,
            { scaleX: 1.15, scaleY: 1.15 }, // 先移动超过目标位置
            50,
            Laya.Ease.linearIn, // 使用指数缓动增强回弹感
            Laya.Handler.create(this, () => {
                // 回弹到最终位置
                Laya.Tween.to(
                    this,
                    { scaleX: 0.2, scaleY: 0.2 },
                    200,
                    Laya.Ease.linearIn, // 使用弹性缓动
                    Laya.Handler.create(this, () => {
                        // 显示关闭按钮
                        // 动画完成后隐藏
                        this.visible = false;
                    })
                );
            })
        );
    }
    public destroy(): void {
        Laya.timer.clear(this, this.nextBanner);
        // Laya.stage.off(Laya.Event.RESIZE, this, this.onResize);
        this.offAll();
        super.destroy();
    }

    private onWatchAD() {
        if (this.adAddress && this.adAddress.length > 0) {
            window.open(this.adAddress, "_blank");
        }
        // window.open("https://cryptoarena.io/", "_blank");
    }
}
