const { regClass } = Laya;
import GameSetting from "../../global/GameSetting";
import SheetDataManager from "../../global/SheetDataManager";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import { CoinsBoxBase } from "./CoinsBox.generated";

@regClass('7P9MlqipSaG6QoKpQowDbQ==')
export class CoinsBox extends CoinsBoxBase {
    coins: any[] = [
        [3022, 2],
        [3001, 2],
        [3011, 2],
        [3013, 4],
        [3010, 2],
        [3007, 4],
        [3006, 6],
        [3015, 2],
        [3016, 2],
        [3005, 0]
    ];

    onEnable(): void {
        let dWidth = (Laya.stage.width - GameSetting.DESIGN_WIDTH) / 2;
        this.img_coinsBg.right -= dWidth;
        console.log("dWidth: " + dWidth);

        this.updateLocalAssets();

        Signal.on(GameEvent.ROLE_INFO_CHANGE, this, this.updateLocalAssets);
        Signal.on(GameEvent.UPDATE_LOCAL_WALLET_LIST_EVENT, this, this.updateLocalAssets);

        this.coins = SheetDataManager.getGeneralValueById(19);

        this.list_coin.array = this.coins;
    }

    onDisable(): void {
        Signal.off(GameEvent.ROLE_INFO_CHANGE, this, this.updateLocalAssets);
        Signal.off(GameEvent.UPDATE_LOCAL_WALLET_LIST_EVENT, this, this.updateLocalAssets);
    }

    /**
     * 我的资产：My Assets
        BTC 8位小数: 9.12345678
        ETH 4位小数：999.1234
        TOX 2位小数：999,999.12
        USDT 2位小数：999,999.12
        积分：0位小数：999,999
     */

    private updateLocalAssets(): void {
        this.list_coin.refresh();
    }
}
