class AiSnakeManager extends SnakeManagerBase {
    protected static _instance: AiSnakeManager | null = null;

    // 碰撞检测间隔计数器（用于优化性能，每几帧检测一次碰撞）
    private _checkSnakeColSpace: number = 0;

    private upgradeSnakeKey: string;

    public static getInstance(): AiSnakeManager {
        if (!AiSnakeManager._instance) {
            AiSnakeManager._instance = new AiSnakeManager();
        }
        return AiSnakeManager._instance;
    }

    /**
     * 创建一条蛇，并添加到管理器中
     * @param pos 蛇的初始位置（Laya.Point）
     * @param dir 蛇的初始方向（Vec2 类型）
     * @param len 蛇的骨骼数量
     * @param snakeType 蛇的类型，默认为其他蛇
     */
    public createSnake(roomPlayerDto: com.snake.socket.PlayerObject): Snake {
        if (this.container == null) {
            console.log(roomPlayerDto.roleId + " 无法添加 container is null");
            return;
        }
        let newSnake = new AiSnake(this.container, roomPlayerDto);

        if (this.matchHeroSprDic.get(roomPlayerDto.roleId)) {
            throw new Error(roomPlayerDto.roleId + " 被重复添加！");
        }
        this.matchHeroSprDic.set(roomPlayerDto.roleId, newSnake);
        // this.snakes.push(newSnake);
        console.log("createSnake: " + roomPlayerDto.roleId, GlobalDataManager.playerDto.pid);
        if (GlobalDataManager.playerDto.pid == roomPlayerDto.roleId) {
            this.selfSnake = newSnake;
            // AiSnakeManager.instance.selfSnake = newSnake;
        }
        // 添加蛇皮到碰撞四叉树中
        // this.collision.addSnake(newSnake.getSkins());
        return newSnake;
    }
    removeSnake(roleId: string) {
        // console.log("============== PVE removeSnake: " + roleId);
        var snake: Snake = this.matchHeroSprDic.get(roleId);
        if (snake) {
            snake.destroy();
            this.matchHeroSprDic.remove(roleId);
            
            if(this.upgradeSnakeKey && this.upgradeSnakeKey == roleId){
                this.upgradeSnakeKey = null;
            }
        } else {
            console.log("removeSnake error: " + roleId);
        }
    }
    /**
     * 设置蛇的目标旋转方向
     * @param snakeType 蛇类型
     * @param dir 目标方向（Vec2 类型）
     */
    public rorate(snakeType: number, direction: number): void {
        if (snakeType === Constants.snakeType.SELF) {
            if (this.selfSnake && this.selfSnake.tag) {
                this.selfSnake.rotate(direction, false);
            }
        } else {
            // 可扩展其他类型蛇的旋转逻辑
        }
    }

    /**
     * 更新蛇的移动速率
     * @param snakeType 蛇类型
     * @param rate 速率值
     */
    public updateSpeedRate(snakeType: number, rate: number): void {
        if (snakeType === Constants.snakeType.SELF && this.selfSnake && this.selfSnake.tag) {
            this.selfSnake.updateSpeedRate(rate, false);
        } else {
            // 可扩展其他类型蛇的速率更新逻辑
        }
    }

    /**
     * 检查蛇是否碰撞死亡：
     * - 检查蛇头是否撞边界
     * - 检查蛇头与其他蛇之间的碰撞
     */
    public checkAllSnakeCollision(isLogicSnake: boolean, hasConfirmed: boolean): void {
        // 碰撞检测优化：每几帧检测一次碰撞
        this._checkSnakeColSpace -= 1;
        if (this._checkSnakeColSpace < 0) {
            // 重置碰撞检测计数器
            this._checkSnakeColSpace = 3; // 每3帧检测一次

            var snakes = this.matchHeroSprDic.getMap();
            for (const [roleId, snake] of snakes) {
                var playerSnake = snake as Snake;
                if (playerSnake && playerSnake.tag) {
                    // console.log("checkAllSnakeCollision roleId: ", playerSnake.tag.roleId);

                    CollisionSystem.checkCollisionsWithPve(playerSnake as AiSnake, null, this.collision, hasConfirmed);
                }
            }
        }
    }

    //=============== AI BEGIN ==================

    private spawnTimer: number = 0;
    private snakeUnKey: number = 0;
    async spawnSnakes() {
        var members = [];
        var initCount = Constants.snake.initCount - 1;
        var names = await Quick.getNpcNames(initCount);

        for (let j = 1; j <= initCount; j++) {
            var playerName = names[j - 1];
            var playerObject: com.snake.socket.PlayerObject = this.spawnRandomPlayerObject(playerName, false, false);

            members.push(playerObject);
        }
        return members;
    }
    spawnRandomPlayerObject(playerName: string, needWudi: boolean = true, isSelf: boolean = false) {
        // 获取地图尺寸（全局配置中）
        const mapWidth = Constants.mapSize.width;
        const mapHeight = Constants.mapSize.height;
        var offsetDistance = Constants.mapSize.offsetDistance;
        var bornX: number = MathUtil.randomRange(offsetDistance, mapWidth - offsetDistance);
        var bornY: number = MathUtil.randomRange(offsetDistance, mapHeight - offsetDistance);

        var totalLen: number = MathUtil.randomInt(Constants.snake.aiMinLen, Constants.snake.aiMaxLen);
        var inScreen = false;
        if (!isSelf) {
            if (SnakeManager.getInstance().selfSnake) {
                var selfHeadPos = SnakeManager.getInstance().selfSnake.getHeadPosition(false);

                var offsetH = 100;

                if (
                    bornX > selfHeadPos.x - Laya.stage.width / 2 - offsetH &&
                    bornX < selfHeadPos.x + Laya.stage.width / 2 + offsetH &&
                    bornY > selfHeadPos.y - Laya.stage.height / 2 - offsetH &&
                    bornY > selfHeadPos.y + Laya.stage.height / 2 + offsetH
                ) {
                    //如果在视窗内，则改为长度小的蛇
                    inScreen = true;

                    if (totalLen > Constants.snake.aiMidLen) {
                        totalLen = MathUtil.randomInt(Constants.snake.aiMinLen, Constants.snake.aiMidLen);
                    }
                } else {
                    // const obsDir = Vec2.create(bornX, bornY).sub(selfHeadPos);
                    // var dir = obsDir.getRotation();
                }
            }
            // if (totalLen > 12) {
            //     needWudi = false;
            // }
        }

        // 计算到各边界的距离
        const leftDist = bornX;
        const rightDist = mapWidth - bornX;
        const topDist = bornY;
        const bottomDist = mapHeight - bornY;
        const minDist = Math.min(leftDist, rightDist, topDist, bottomDist);
        // console.debug(
        //     "spawnRandomPlayerObject playerName: ",
        //     playerName + ", inScreen: ",
        //     inScreen + ", leftDist: ",
        //     totalLen + ", leftDist: ",
        //     leftDist + ", rightDist: ",
        //     rightDist + ", topDist: ",
        //     topDist + ", bottomDist: ",
        //     bottomDist + ", minDist: ",
        //     minDist
        // );

        let direction: number;

        // 根据最近边界和相邻边界距离生成安全方向
        if (minDist === leftDist) {
            // 左边界：判断垂直位置（上/下）
            if (topDist < bottomDist) {
                // 靠近上边：右下方（0°~45°）
                direction = Math.random() * 45;
            } else if (topDist > bottomDist) {
                // 靠近下边：右上方（315°~360°）
                direction = Math.random() * 45 + 315;
            } else {
                // 中部：右方（-45°~45° → 315°~360° 和 0°~45°）
                direction = Math.random() * 90 - 45;
            }
        } else if (minDist === rightDist) {
            // 右边界：判断垂直位置（上/下）
            if (topDist < bottomDist) {
                // 靠近上边：左下方（135°~180°）
                direction = 135 + Math.random() * 45;
            } else if (topDist > bottomDist) {
                // 靠近下边：左上方（180°~225°）
                direction = 180 + Math.random() * 45;
            } else {
                // 中部：左方（135°~225°）
                direction = 180 + Math.random() * 90 - 45;
            }
        } else if (minDist === topDist) {
            // 上边界：判断水平位置（左/右）
            if (leftDist < rightDist) {
                // 靠近左边：右下方（45°~90°）
                direction = 45 + Math.random() * 45;
            } else if (leftDist > rightDist) {
                // 靠近右边：左下方（90°~135°）
                direction = 90 + Math.random() * 45;
            } else {
                // 中部：下方（45°~135°）
                direction = 90 + Math.random() * 90 - 45;
            }
        } else {
            // 下边界：判断水平位置（左/右）
            if (leftDist < rightDist) {
                // 靠近左边：右上方（270°~315°）
                direction = 270 + Math.random() * 45;
            } else if (leftDist > rightDist) {
                // 靠近右边：左上方（225°~270°）
                direction = 225 + Math.random() * 45;
            } else {
                // 中部：上方（225°~315°）
                direction = 270 + Math.random() * 90 - 45;
            }
        }

        // 规范化角度到 0-359
        direction = (direction + 360) % 360;
        direction = Math.floor(direction);

        if (!isSelf && !inScreen && totalLen > Constants.snake.aiMidLen) {
            if (SnakeManager.getInstance().selfSnake) {
                // 计算方向向量
                var radian = (direction * Math.PI) / 180;

                const dirVector = Vec2.create(Math.cos(radian), -Math.sin(radian));

                var lastBone = Vec2.create(bornX, bornY);
                const stiffnessWithSpeed = 0.6 * 8 * totalLen; // 弹性系数 (0~1) *速度* 蛇长度
                var tmpPos = lastBone.add(dirVector.mul(stiffnessWithSpeed));

                var selfHeadPos = SnakeManager.getInstance().selfSnake.getHeadPosition(false);

                var offsetH = 50;

                if (
                    tmpPos.x > selfHeadPos.x - Laya.stage.width / 2 - offsetH &&
                    tmpPos.x < selfHeadPos.x + Laya.stage.width / 2 + offsetH &&
                    tmpPos.y > selfHeadPos.y - Laya.stage.height / 2 - offsetH &&
                    tmpPos.y > selfHeadPos.y + Laya.stage.height / 2 + offsetH
                ) {
                    //如果尾部在视窗内，则改为长度小的蛇

                    totalLen = MathUtil.randomInt(Constants.snake.aiMinLen, Constants.snake.aiMidLen);
                }
            }
        }

        var playerObject: com.snake.socket.PlayerObject = this.getPlayerObjectByPos(playerName, totalLen, bornX, bornY, direction, needWudi, isSelf);
        return playerObject;
    }

    playerLen() {
        var size = this.matchHeroSprDic.size;
        return size;
    }
    private async spawnSnake(): Promise<void> {
        var maxCount = MathUtil.randomInt(Constants.snake.initCount, Constants.snake.maxCount);
        if (this.playerLen() >= maxCount) return;
        var nameStr = await Quick.getOneNpcNames();
        var playerName = nameStr;
        var playerObject: com.snake.socket.PlayerObject = this.spawnRandomPlayerObject(playerName, true, false);
        this.createSnake(playerObject);
    }

    public update(dt: number): void {
        // 定时生成蛇
        this.spawnTimer += dt;
        if (this.spawnTimer >= Constants.snake.spawnInterval) {
            this.spawnTimer = 0;
            this.spawnSnake();
        }
    }
    private testSkinIndex = 0;

    getPlayerObjectByPos(
        playerName: string,
        totalLen: number,
        bornX: number,
        bornY: number,
        direction: number,
        needWudi: boolean = true,
        isSelf: boolean = false
    ) {
        console.debug("getPlayerObjectByPos: ", playerName, " born: ( " + bornX, bornY + " ), dir: " + direction);
        var pos: Vec2 = new Vec2(bornX, bornY);
        var userName = "";
        var roleId;
        var snakeId: number = 0;
        var skinId: number = 0;
        var countryId: number = 0;

        var player: com.snake.socket.PlayerObject = new com.snake.socket.PlayerObject();

        player.aimDir = player.direction = direction;

        player.speed = 1;
        player.state = true;

        player.enterTime = Laya.timer.currTimer;
        player.oprTime = Laya.timer.currTimer;
        if (needWudi) {
            player.wdTime = Laya.timer.currTimer + 3000;
        } else {
            player.wdTime = Laya.timer.currTimer;
        }
        if (isSelf) {
            var playerDto = GlobalDataManager.playerDto;
            var _snakeUnKey = playerDto.snakeId; //出站的蛇
            var snakeVo = KnapsackManager.getSnakeItemById(_snakeUnKey);
            snakeId = snakeVo.id;
            skinId = snakeVo.skin;
            countryId = playerDto.country;
            totalLen = snakeVo.snakeItem.initLength;
            userName = playerDto.name;
            roleId = playerDto.pid;
            player.roleId = roleId + "";
            var attr = snakeVo.attr;
            player.attr = attr;

            for (let i = 0; i < attr.length; i++) {
                if (attr[i]) {
                    let attrItem = attr[i].split(",");
                    let index = attrItem[0];
                    let value = attrItem[1];
                    if (index == "1") {
                        var newLen = parseInt(value);
                        var len = totalLen;
                        totalLen = newLen;
                        console.log("ATTR: 计算长度：后端len: " + len + ", newLen: " + newLen);
                    }
                }
            }
        } else {
            this.snakeUnKey += 1;

            roleId = Constants.snake.aiPrefix + this.snakeUnKey;
            var snakeTypeLen = SheetDataManager.m_dicSnakes.keys.length;
            var snakeIndex: number = Math.floor(Math.random() * snakeTypeLen);
            snakeId = SheetDataManager.m_dicSnakes.keys[snakeIndex];

            var bigRandom = Math.random();
            if (bigRandom < 0.4) {
                //免费蛇40%左右

                    skinId = Constants.snake.skin1Ids[0];

            } else {
                //付费蛇 60%
                var skinType2Len = Constants.snake.skin2Ids.length;
                var skinIndex2: number = Math.floor(Math.random() * skinType2Len);
                skinId = Constants.snake.skin2Ids[skinIndex2];
            }

            if (!this.upgradeSnakeKey){//留一条升级蛇
                var skinType3Len = Constants.snake.skin3Ids.length;
                var skinIndex3: number = Math.floor(Math.random() * skinType3Len);
                skinId = Constants.snake.skin3Ids[skinIndex3];
                this.upgradeSnakeKey = roleId;
            }
            
            //=============== TEST BEGIN ================
            // var skinTypeLen = Constants.snake.skinIds.length;
            // console.error("test skin end this.testSkinIndex: " + this.testSkinIndex + ", skinTypeLen: " + skinTypeLen);
            // if (this.testSkinIndex >= skinTypeLen) {
                
            //     this.testSkinIndex = 0;
            // }
            // var skinIndex = this.testSkinIndex;
            // this.testSkinIndex++;
            // skinId = Constants.snake.skinIds[skinIndex];
            //=============== TEST END ================


            var countryTypeLen = SheetDataManager.m_dicCountry.keys.length;
            var countryIndex: number = Math.floor(Math.random() * countryTypeLen);
            countryId = SheetDataManager.m_dicCountry.keys[countryIndex];

            player.roleId = roleId;
            userName = playerName; //设置NPC名字
            //暂时用NPC roleId
            if (GameSetting.Debug == 2) {
                userName = player.roleId;
            }
        }
        var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(snakeId);
        if (totalLen > snakeItem.maxLength) {
            totalLen = snakeItem.maxLength;
        }

        player.userName = userName;
        player.snakeId = snakeId;
        player.skin = skinId;
        player.country = countryId;
        var baseSpeed = snakeItem.baseSpeed;
        // if (!isSelf) {
        //     var calMaxLen = this.calculateMaxLength(bornX, bornY, direction, baseSpeed, 0.6, snakeItem.bodyRadius, snakeItem.intervalBoneToDrawSkin);
        //     var randomTotalLen = totalLen;
        //     if (calMaxLen < totalLen) {
        //         totalLen = calMaxLen;
        //     }
        //     console.debug("AI: 计算长度：randomTotalLen: " + randomTotalLen + ", calMaxLen: " + calMaxLen + ", totalLen: " + totalLen);
        // }
        player.length = totalLen * snakeItem.intervalBoneToDrawSkin;
        var snakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(SheetDataManager.m_dicSnakeLengthRules, [
            snakeId,
            totalLen
        ]);

        player.score = snakeLengthRuleItem.accumulatePoints;
        player.kills = 0;

        var snakePos: com.snake.socket.SnakeObject[] = [];

        // 计算方向向量
        var radian = (player.direction * Math.PI) / 180;

        const dirVector = Vec2.create(Math.cos(radian), -Math.sin(radian));

        // 初始化骨骼点
        for (let i = 0; i < player.length; i++) {
            let tmpPos: Vec2;
            if (i === 0) {
                tmpPos = pos ? pos : Vec2.create(0, 0);
            } else {
                // 计算新骨骼点：前一个骨骼点加上方向向量（乘以速度）
                var lastSnakePos = snakePos[i - 1];
                var lastBone = Vec2.create(lastSnakePos.loc.x, lastSnakePos.loc.y);
                const stiffness = 0.6; // 弹性系数 (0~1)
                tmpPos = lastBone.add(dirVector.mul(baseSpeed * stiffness));
            }
            var head: com.snake.socket.SnakeObject = new com.snake.socket.SnakeObject();
            var pointObject = new com.snake.socket.PointObject();
            //不是自己的蛇，长度处理不出界
            if (
                !isSelf &&
                (tmpPos.x < Constants.mapSize.offsetX + snakeItem.collisionBodyRadius ||
                    tmpPos.x > Constants.mapSize.width - (Constants.mapSize.offsetX + snakeItem.collisionBodyRadius) ||
                    tmpPos.y < Constants.mapSize.offsetY + snakeItem.collisionBodyRadius ||
                    tmpPos.y > Constants.mapSize.height - (Constants.mapSize.offsetY + snakeItem.collisionBodyRadius))
            ) {
                //超出边界的话，则长度减少
                player.length = i;
                totalLen = Math.floor(player.length / snakeItem.intervalBoneToDrawSkin);
                var snakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(SheetDataManager.m_dicSnakeLengthRules, [
                    snakeId,
                    totalLen
                ]);
                if (!snakeLengthRuleItem) {
                    console.log("player.length: " + player.length + ", totalLen: " + totalLen);
                    break;
                }
                player.score = snakeLengthRuleItem.accumulatePoints;
                break;
            }
            // // 强制约束在墙内
            // pointObject.x = Math.max(Constants.mapSize.offsetX, Math.min(tmpPos.x, Constants.mapSize.width - Constants.mapSize.offsetX));
            // pointObject.y = Math.max(Constants.mapSize.offsetY, Math.min(tmpPos.y, Constants.mapSize.height - Constants.mapSize.offsetY));

            pointObject.x = tmpPos.x;
            pointObject.y = tmpPos.y;
            // console.debug("bone: ", i, " pos: ", tmpPos);
            head.loc = pointObject;
            snakePos[i] = head;
        }

        player.snake = snakePos;
        return player;
    }

    calculateMaxLength(
        bornX: number,
        bornY: number,
        direction: number, // 0-359 度
        baseSpeed: number,
        stiffness: number,
        bodyRadius: number,
        intervalBoneToDrawSkin: number // 每多少骨骼一段皮肤
    ): number {
        // 地图边界
        const minX = Constants.mapSize.offsetX + bodyRadius;
        const maxX = Constants.mapSize.width - Constants.mapSize.offsetX - bodyRadius;
        const minY = Constants.mapSize.offsetY + bodyRadius;
        const maxY = Constants.mapSize.height - Constants.mapSize.offsetY - bodyRadius;

        // 角度转弧度
        const rad = (direction * Math.PI) / 180;

        // 方向向量 (单位向量)
        const dirX = Math.cos(rad);
        const dirY = Math.sin(rad);

        // 反方向单位向量
        const revDirX = -dirX;
        const revDirY = -dirY;

        // 计算到边界的最大距离（反方向）
        // 计算和四条边界的交点距离，取其中最小的正距离

        // 边界点与起点距离计算函数
        function distToBoundary(dirComp: number, pos: number, minBound: number, maxBound: number): number | null {
            if (dirComp === 0) return null;
            if (dirComp > 0) {
                // 向正方向
                return (maxBound - pos) / dirComp;
            } else {
                // 向负方向
                return (minBound - pos) / dirComp;
            }
        }

        // 计算四个边界距离（可能是负数或无穷）
        const distX = distToBoundary(revDirX, bornX, minX, maxX);
        const distY = distToBoundary(revDirY, bornY, minY, maxY);

        // 取正的距离，且最小的一个
        let candidates = [];
        if (distX !== null && distX > 0) candidates.push(distX);
        if (distY !== null && distY > 0) candidates.push(distY);
        if (candidates.length === 0) {
            // 理论上不会发生，返回0
            return 0;
        }
        const maxDist = Math.min(...candidates);

        // 蛇身骨骼间距长度单位
        const stepLen = baseSpeed * stiffness;

        // 最大骨骼数
        const maxBones = Math.floor(maxDist / stepLen);

        // 返回皮肤数量 = 骨骼数量 / intervalBoneToDrawSkin，向下取整
        const skinCount = Math.floor(maxBones / intervalBoneToDrawSkin);

        return skinCount;
    }

    //=============== AI END ==================
}
export default AiSnakeManager;
