const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { RoomItem } from "../../data/sheetItem/RoomItem";
import AssetManager from "../../manager/AssetManager";
import { ChooseCoinDialogBase } from "./ChooseCoinDialog.generated";
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";

@regClass('k+A/FTp8Sg2U/4wdaJY5aA==')
export class ChooseCoinDialog extends ChooseCoinDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private tokenIndex: number = 0;
    private roomData: RoomItem;
    private tokenInfoList: Array<{symbol: string, address: string, index: number, symbolId: number}> = [];
    private originalTicketType: any[] = []; // 保存原始的代币列表数据
    private currentSelectedTokenId: any = null; // 保存当前选中的代币ID
    private isUserSelect: boolean = false; // 标记是否是用户主动选择

    public constructor() {
        super();
    }

    onEnable(): void {
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
        
        // 添加输入框监听
        this.input_address.on(Laya.Event.INPUT, this, this.onInputChange);
        
        // 添加列表点击监听
        this.list_token.on(Laya.Event.MOUSE_DOWN, this, this.onListMouseDown);
        
        // this.okBtn.on(Laya.Event.CLICK, this, () => {
        //     this.close();
        // });
        // const diamonData = KnapsackManager.getAllKnapsackItems().find((item) => item.id === 10001);
        // if (diamonData) {
        //     console.log(diamonData);
        //     this.tf_score.text = `${parseFloat(diamonData.num.toFixed(4)).toString()}`;
        // }

        // // this.tf_ruleTitle.text = GameLanguageMgr.getLanguage(610103);
        // this.tf_ruleContent.text = GameLanguageMgr.getLanguage(610104);
    }

    public setOpenData(data: any) {
        console.log("data", data);
        this.tokenIndex = data.tokenIndex;
        this.roomData =  data.roomData;
        this.setListData()
    }

    private setListData() {
        this.originalTicketType = [...this.roomData.ticketType]; // 保存原始数据
        this.list_token.array = this.roomData.ticketType;
        this.list_token.selectedIndex = this.tokenIndex;
        // 保存当前选中的代币ID
        if (this.tokenIndex >= 0 && this.tokenIndex < this.originalTicketType.length) {
            this.currentSelectedTokenId = this.originalTicketType[this.tokenIndex];
        }
        this.getAllTokenInfo();
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_token.selectedIndex == index);
        }
    }

    /**
     * 列表鼠标按下事件，标记用户选择
     */
    private onListMouseDown(): void {
        this.isUserSelect = true;
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        // 只有当用户点击选择时才触发
        if (index != -1 && this.isUserSelect) {
            // 重置标记
            this.isUserSelect = false;
            
            // 获取选中项的symbolId
            const selectedSymbolId = this.list_token.array[index];
            
            // 更新当前选中的代币ID
            this.currentSelectedTokenId = selectedSymbolId;
            
            // 在原始列表中查找对应的索引
            const originalIndex = this.originalTicketType.findIndex(item => item === selectedSymbolId);
            
            // 发送选择事件，传递选中的代币信息
            const tokenData = {
                tokenIndex: originalIndex !== -1 ? originalIndex : index, // 使用原始索引，如果找不到则使用当前索引
                tokenId: this.currentSelectedTokenId,
                symbolId: selectedSymbolId, // 添加symbolId
                roomData: this.roomData
            };
            Signal.event(GameEvent.EVENT_TOKEN_SELECTED, tokenData);
            
            // 关闭弹窗
            this.close();
        }
    }

    /**
     * 监听输入框变化，筛选列表
     */
    private onInputChange(): void {
        const inputText = this.input_address.text.toLowerCase();
        
        if (!inputText) {
            // 如果输入为空，恢复原始列表
            this.list_token.array = this.originalTicketType;
            // 恢复原始选中状态
            this.restoreSelectedIndex();
            return;
        }
        
        // 根据输入内容筛选token（同时筛选symbol和address）
        const filteredIndices: number[] = [];
        this.tokenInfoList.forEach(tokenInfo => {
            if (tokenInfo.symbol.toLowerCase().includes(inputText) || 
                tokenInfo.address.toLowerCase().includes(inputText)) {
                filteredIndices.push(tokenInfo.index);
            }
        });
        
        // 筛选原始数据中符合条件的项
        const filteredData = filteredIndices.map(index => this.originalTicketType[index]);
        
        // 更新列表数据
        this.list_token.array = filteredData;
        
        // 恢复选中状态（如果筛选结果中包含原选中项）
        this.restoreSelectedIndex();
    }
    
    /**
     * 恢复选中状态
     */
    private restoreSelectedIndex(): void {
        if (this.currentSelectedTokenId) {
            // 在当前列表中查找原选中项的新索引
            const newIndex = this.list_token.array.findIndex(item => item === this.currentSelectedTokenId);
            if (newIndex !== -1) {
                // 如果找到了，设置为选中状态
                this.list_token.selectedIndex = newIndex;
            } else {
                // 如果没找到，清除选中状态
                this.list_token.selectedIndex = -1;
            }
        }
    }

    private getAllTokenInfo(): void {
        this.tokenInfoList = [];
        for(let i = 0; i < this.roomData.ticketType.length; i++) {
            let tokenData = AssetManager.getTokenDataBySyId(this.list_token.array[i]);
            if(tokenData){
                this.tokenInfoList.push({
                    symbol: tokenData.symbol,
                    address: tokenData.tokenAddress || "",
                    index: i,
                    symbolId: tokenData.symbolId
                });
            }
        }
        console.log("tokenInfoList", this.tokenInfoList);
    }

    onDisable(): void {
        // 清理事件监听
        this.input_address.off(Laya.Event.INPUT, this, this.onInputChange);
        this.list_token.off(Laya.Event.MOUSE_DOWN, this, this.onListMouseDown);
    }
}
