const { regClass } = Laya;
import { EnumMatch } from "../../data/enumData/EnumMatch";
import Snake from "../../game/snake/Snake";
import { StringTool } from "../../utils/StringTool";
import MatchModel from "./MatchModel";
import { MatchRankListItemBase } from "./MatchRankListItem.generated";

@regClass('XTVFXeI/R768e0Elv/ePAA==')
export class MatchRankListItem extends MatchRankListItemBase {
    public snake: Snake;
    private isAddEvent: boolean = false;
    public constructor() {
        super();
    }

    private addEvent() {
        if (!this.isAddEvent) {
            this.isAddEvent = true;
        }
    }

    public set dataSource(value: any) {
        this.snake = value as Snake;
        if (!this.snake || !this.snake.tag) {
            return;
        }
        this.addEvent();
        this.setCurrentOutPut();
    }

    setCurrentOutPut() {
        if (this.snake.tag) this.tf_rank.text = this.snake.rankNum + ".  " + StringTool.abbreviateString(this.snake.tag.userName);
        var score = 0;
        if (MatchModel.matchDto.matchType == EnumMatch.MATCH_TYPE_PVE) {
            score = this.snake.getScore(false);
        } else {
            score = this.snake.getScore(true);
        }

        if (this.snake.rankNum == 1) {
            this.tf_kill.text = `<font><img src='res/match2/img_phb_icon2.png'/>${score}</font>`;
        } else {
            this.tf_kill.text = `<font>${score}</font>`;
        }

        if (this.snake.isSelf) {
            this.tf_rank.color = "#ffe155";

            this.tf_kill.color = "#ffe155";
        } else {
            this.tf_rank.color = "#ffffff";
            this.tf_kill.color = "#ffffff";
        }
    }
}
