const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import PlatFormManager from "../../common/PlatFormManager";
import { NoticeDetailDto } from "../../data/dto/NoticeDetailDto";
import { NoticeDto } from "../../data/dto/NoticeDto";
import { NoticeDialogBase } from "./NoticeDialog.generated";

@regClass('iB7UvqEcQ1GFKaVEIy6Bmw==')
export class NoticeDialog extends NoticeDialogBase {
    private canClose: boolean = true;
    list: NoticeDetailDto[];
    pageNo: number;
    pageTotal: number;
    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_refresh.on(Laya.Event.CLICK, this, this.onRefresh);
        // 注册超链接点击事件
        this.alertDesc.on(Laya.Event.LINK, this, this.onLink);
        this.btn_left.on(Laya.Event.CLICK, this, this.onChangePage, [false]);
        this.btn_right.on(Laya.Event.CLICK, this, this.onChangePage, [true]);
    }

    onLink(data: any) {
        console.log("点击了超链接：" + data);
        // 这里可以执行更多的链接点击后的操作
    }
    onRefresh() {
        PlatFormManager.reload();
    }

    public setOpenData(data: any) {
        if (data) {
            var type: number = data[0];
            var noticeDto: NoticeDto = data[1];
            this.list = noticeDto.list;
            this.pageNo = 1;
            this.pageTotal = this.list.length;
            if (this.pageTotal < 2) {
                this.box_page.visible = false;
            }
            this.updatePageList();
            if (type == 1) {
                this.canClose = false;
                var btnClose: Laya.Button = this.getChildByName("close") as Laya.Button;
                btnClose.visible = false;
                this.btn_refresh.visible = true;
            } else {
                this.btn_refresh.visible = false;
            }
        }
    }

    async onChangePage(isAdd: boolean) {
        if (isAdd) {
            this.pageNo++;
        } else {
            if (this.pageNo <= 1) return;
            this.pageNo--;
        }
        this.updatePageList();
    }

    updatePageList() {
        this.txt_page.text = this.pageNo + "/" + this.pageTotal;
        this.btn_left.disabled = this.pageNo <= 1;
        this.btn_right.disabled = this.pageNo >= this.pageTotal;
        this.setNoticeDetail();
    }

    public setNoticeDetail() {
        if (this.pageNo) {
            var noticeDetailDto: NoticeDetailDto = this.list[this.pageNo - 1];
            if (noticeDetailDto) {
                this.alertTitle.text = GameLanguageMgr.getMultiLan(noticeDetailDto.title);
                this.alertDesc.text = GameLanguageMgr.getMultiLan(noticeDetailDto.contents);
            }
        }
    }

    onDisable(): void {}

    close(type?: string): void {
        if (this.canClose) super.close(type);
    }
}
